console.log('1 — Synchronous');      // runs immediately

setTimeout(() => {
  console.log('3 — Timer callback');
}, 0);

Promise.resolve().then(() => {
  console.log('2 — Microtask');       // runs before timer!
});

console.log('4 — Synchronous again');

// Output order: 1, 4, 2, 3
// Why?
// 1. Call stack runs synchronous code: 1, 4
// 2. Microtask queue (Promises): 2  ← higher priority!
// 3. Task queue (setTimeout): 3

// Creating a Promise
const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms));

const fetchUser = (id) => new Promise((resolve, reject) => {
  if (id <= 0) {
    reject(new Error('Invalid ID'));
    return;
  }
  // Simulate async
  setTimeout(() => resolve({ id, name: 'Alice' }), 500);
});

// Consuming: .then / .catch / .finally
fetchUser(1)
  .then(user => {
    console.log('Got user:', user.name);
    return user.id; // return value is passed to next .then
  })
  .then(id => fetchUser(id + 1)) // chaining — returns a Promise
  .then(nextUser => console.log(nextUser))
  .catch(err => console.error('Error:', err.message))
  .finally(() => console.log('Done — hide loading spinner'));

// Promise combinators
await Promise.all([f1(), f2(), f3()]);       // all resolve (fails if any fails)
await Promise.allSettled([f1(), f2()]);      // wait for all, get each result
await Promise.race([f1(), timeout(5000)]);   // first to settle wins
await Promise.any([f1(), f2()]);            // first to resolve

// async functions always return a Promise
async function getProfile(userId) {
  // await pauses execution until Promise resolves
  const user = await fetchUser(userId);
  const posts = await fetchPosts(user.id);
  const comments = await fetchComments(posts[0].id);
  return { user, posts, comments };
}

// Error handling with try/catch
async function safeGetProfile(userId) {
  try {
    const user = await fetchUser(userId);
    return user;
  } catch (error) {
    console.error('Failed to fetch user:', error.message);
    return null; // graceful fallback
  } finally {
    hideLoadingSpinner();
  }
}

// Parallel execution (don't await inside loop!)
async function loadAll(userIds) {
  // ❌ Sequential: 3 seconds total if each takes 1s
  // for (const id of userIds) await fetchUser(id);

  // ✅ Parallel: 1 second total
  const users = await Promise.all(userIds.map(id => fetchUser(id)));
  return users;
}

// GET request
async function getUsers() {
  const response = await fetch('https://api.example.com/users');

  if (!response.ok) {
    throw new Error(`HTTP error! Status: ${response.status}`);
  }

  const users = await response.json(); // parse JSON body
  return users;
}

// POST request
async function createUser(userData) {
  const response = await fetch('https://api.example.com/users', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${getToken()}`
    },
    body: JSON.stringify(userData)
  });

  if (!response.ok) {
    const error = await response.json();
    throw new Error(error.message);
  }

  return response.json();
}

// Abort a request
const controller = new AbortController();

const fetchPromise = fetch('/api/slow-endpoint', {
  signal: controller.signal
});

// Cancel after 5 seconds
setTimeout(() => controller.abort(), 5000);

// Custom error classes
class ApiError extends Error {
  constructor(message, status, data) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.data = data;
  }
}

class NotFoundError extends ApiError {}
class AuthError extends ApiError {}

// Robust fetch wrapper
async function apiFetch(url, options = {}) {
  try {
    const response = await fetch(url, options);
    const data = await response.json();

    if (response.status === 401) throw new AuthError('Unauthorized', 401, data);
    if (response.status === 404) throw new NotFoundError('Not Found', 404, data);
    if (!response.ok) throw new ApiError('API Error', response.status, data);

    return data;
  } catch (error) {
    if (error instanceof ApiError) throw error; // re-throw known errors
    throw new ApiError('Network error: ' + error.message, 0);
  }
}

// Retry with exponential backoff
async function fetchWithRetry(url, maxRetries = 3) {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await apiFetch(url);
    } catch (error) {
      if (error.status === 401 || attempt === maxRetries) throw error;
      const delay = Math.pow(2, attempt) * 100; // 200ms, 400ms, 800ms
      await new Promise(r => setTimeout(r, delay));
    }
  }
}
